    if (filled($triggerId)) {
        $triggerAttributes = $triggerAttributes->merge(['id' => $triggerId]);
    }

    if (filled($listboxId)) {
        $triggerAttributes = $triggerAttributes->merge(['aria-controls' => $listboxId]);
